[CmdletBinding()] param([string]$HostName='localhost',[int]$Port=5432,[string]$Database='sigov',[string]$MaintenanceDatabase='postgres',[string]$AdminUser='postgres',[string]$AdminPassword=$env:PGPASSWORD,[string]$AppDbUser='sigov',[string]$AppDbPassword=$env:SIGOV_DB_PASSWORD,[string]$EnvFile=(Join-Path (Split-Path -Parent $PSScriptRoot) '.env.local'))
$ErrorActionPreference='Stop'; if(!(Get-Command psql -ErrorAction SilentlyContinue)){throw 'psql não encontrado.'}; if([string]::IsNullOrWhiteSpace($AppDbPassword)){throw 'Defina AppDbPassword ou SIGOV_DB_PASSWORD.'}
$env:PGPASSWORD=$AdminPassword
$role=$AppDbUser.Replace("'","''"); $password=$AppDbPassword.Replace("'","''"); $db=$Database.Replace('"','""')
$sql="DO `$`$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='$role') THEN CREATE ROLE `"$AppDbUser`" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD '$password'; ELSE ALTER ROLE `"$AppDbUser`" LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD '$password'; END IF; END `$`$; GRANT CONNECT ON DATABASE `"$db`" TO `"$AppDbUser`";"
& psql -X -v ON_ERROR_STOP=1 -h $HostName -p $Port -U $AdminUser -d $MaintenanceDatabase -c $sql | Out-Null; if($LASTEXITCODE){throw 'Falha ao criar/atualizar usuário runtime.'}
& psql -X -v ON_ERROR_STOP=1 -h $HostName -p $Port -U $AdminUser -d $Database -c "GRANT USAGE ON SCHEMA sigov TO `"$AppDbUser`"; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA sigov TO `"$AppDbUser`"; GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA sigov TO `"$AppDbUser`"; ALTER DEFAULT PRIVILEGES IN SCHEMA sigov GRANT SELECT,INSERT,UPDATE,DELETE ON TABLES TO `"$AppDbUser`"; ALTER DEFAULT PRIVILEGES IN SCHEMA sigov GRANT USAGE,SELECT ON SEQUENCES TO `"$AppDbUser`";" | Out-Null; if($LASTEXITCODE){throw 'Falha ao conceder permissões runtime.'}
$env:PGPASSWORD=$AppDbPassword; & psql -X -v ON_ERROR_STOP=1 -h $HostName -p $Port -U $AppDbUser -d $Database -Atqc 'select 1' | Out-Null; if($LASTEXITCODE){throw 'Usuário provisionado, mas o teste runtime falhou.'}; Write-Host "Usuário runtime '$AppDbUser' sincronizado e validado (senha omitida)."
